CREATE TABLE IF NOT EXISTS mobile_otp_challenges (id text PRIMARY KEY, user_id text NOT NULL, phone_cipher text NOT NULL, verification_sid text NOT NULL, channel text NOT NULL, attempts int NOT NULL DEFAULT 0, expires_at timestamptz NOT NULL DEFAULT now()+interval '10 minutes', consumed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mobile_sessions (id text PRIMARY KEY, user_id text NOT NULL, expires_at timestamptz NOT NULL DEFAULT now()+interval '30 days', revoked_at timestamptz);
CREATE TABLE IF NOT EXISTS mobile_rate_limits (bucket text PRIMARY KEY, hits int NOT NULL DEFAULT 1, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS mobile_residence (id text PRIMARY KEY, user_id text NOT NULL UNIQUE, address_cipher text, anchor_cipher text, timezone text NOT NULL, home_hour int NOT NULL, consent_version text NOT NULL, consent_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mobile_residence_samples (enrollment_id text NOT NULL REFERENCES mobile_residence(id) ON DELETE CASCADE, day_index int NOT NULL, qualifies boolean NOT NULL, reason text NOT NULL, sample_cipher text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(enrollment_id,day_index));
